using System.Net;
using System.Reflection;
using Microsoft.AspNetCore.TestHost;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Catalog.Application;
using Shop.Modules.Catalog.Infrastructure;
using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;
public sealed class PublicCatalogReadTests(ApiFactory factory):IClassFixture<ApiFactory>
{
    [Fact] public async Task OneVersionDriftRestartsTheReadAndReturnsOnlyTheSuccessfulAttempt(){var calls=0;var result=await CatalogReadRetry.RunAsync(_=>++calls==1?Task.FromException<int>(new BusinessException("version_conflict","changed")):Task.FromResult(7),CancellationToken.None);Assert.Equal(7,result);Assert.Equal(2,calls);}
    [Fact] public async Task PersistentDriftIsUnavailableInsteadOfAnEmptyOrZeroSuccess(){var calls=0;var e=await Assert.ThrowsAsync<BusinessException>(()=>CatalogReadRetry.RunAsync<int>(_=>{calls++;throw new BusinessException("version_conflict","changed");},CancellationToken.None));Assert.Equal("catalog_unavailable",e.Code);Assert.Equal(2,calls);}
    [Theory][InlineData("invalid_cart")][InlineData("unknown_category")][InlineData("catalog_reindex_required")]
    public async Task ValidationAndMaintenanceFailuresAreNotRetried(string code){var calls=0;var e=await Assert.ThrowsAsync<BusinessException>(()=>CatalogReadRetry.RunAsync<int>(_=>{calls++;throw new BusinessException(code,"expected");},CancellationToken.None));Assert.Equal(code,e.Code);Assert.Equal(1,calls);}
    [Fact] public async Task CancellationBeforeReadDoesNoWork(){using var cancel=new CancellationTokenSource();cancel.Cancel();var calls=0;await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>CatalogReadRetry.RunAsync(_=>{calls++;return Task.FromResult(1);},cancel.Token));Assert.Equal(0,calls);}
    [Fact] public async Task CancellationDuringDriftDoesNotStartAnotherAttempt(){using var cancel=new CancellationTokenSource();var calls=0;await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>CatalogReadRetry.RunAsync<int>(_=>{calls++;cancel.Cancel();throw new BusinessException("version_conflict","changed");},cancel.Token));Assert.Equal(1,calls);}
    [Theory][InlineData("fa")][InlineData("en")]
    public void CheckoutSqlReadsPriceDetailsAndAllEligibilityVersionsInOneProjection(string locale){using var db=new CatalogDbContext(DesignTimeOptions.Create<CatalogDbContext>("catalog"));var sql=CheckoutCatalogQuery.Read(db,locale,["one","two"],DateTimeOffset.Parse("2026-01-01T00:00:00Z")).ToQueryString();foreach(var field in new[]{"PriceRial","Version","Sku","Warranty","SellerId","PublishAt","IsActive"})Assert.Contains(field,sql);Assert.DoesNotContain("ProductMedia",sql);Assert.DoesNotContain("ProductPurchaseMethod",sql);Assert.DoesNotContain("SELECT *",sql);}
    [Theory][InlineData("selected")][InlineData("price-asc")][InlineData("price-desc")][InlineData("newest")]
    public void WinnerProjectionTranslatesItsVariantAndProductAndBrandVersionsTogether(string sort){using var db=new CatalogDbContext(DesignTimeOptions.Create<CatalogDbContext>("catalog"));var filter=CatalogSearchQuery.Create(new(Query:"نسخه",Sort:sort));var matching=CatalogQuery.Match(db,filter,"fa",["cat"],[],DateTimeOffset.Parse("2026-01-01T00:00:00Z"));var sql=CatalogQuery.Winners(matching.Where(c=>c.Product.Id=="one")).ToQueryString();Assert.Contains("Version",sql);Assert.Contains("PriceRial",sql);Assert.Contains("AvailableStockV1",sql);Assert.DoesNotContain("PriceHistory",sql);}
    [Fact] public void RepeatedParentsCoalesceOnlyWhenTheirVersionsAgreeAndBuffersAreCopied(){byte[] value=[0,0,0,0,0,0,0,1];var result=CheckoutCatalogQuery.Versions([new("one",value),new("one",value.ToArray())]);Assert.Single(result);value[^1]=2;Assert.Equal((byte)1,result[0].Version[^1]);Assert.Equal("version_conflict",Assert.Throws<BusinessException>(()=>CheckoutCatalogQuery.Versions([new("one",value),new("one",result[0].Version)])).Code);}
    [Fact] public async Task InvalidExternalSnapshotsFailBeforeCloningOrOpeningSql(){await using var db=new CatalogDbContext(DesignTimeOptions.Create<CatalogDbContext>("catalog"));foreach(var rows in new[]{new[]{new CatalogReadVersion("one",null!)},Enumerable.Range(0,501).Select(i=>new CatalogReadVersion("p"+i,new byte[8])).Append(new("p0",new byte[8])).ToArray()})Assert.Equal("version_conflict",(await Assert.ThrowsAsync<BusinessException>(()=>CatalogReadVersions.EnsureSnapshotsAsync<Shop.Modules.Catalog.Domain.Product>(db,rows,CancellationToken.None))).Code);Assert.Equal(System.Data.ConnectionState.Closed,db.Database.GetDbConnection().State);}
    [Fact] public async Task EmptyCheckoutAndInvalidInputsNeverOpenSql(){using var scope=factory.Services.CreateScope();var reader=scope.ServiceProvider.GetRequiredService<ICheckoutCatalogReader>();Assert.Empty(await reader.ReadCheckoutVariantsAsync("fa",[],CancellationToken.None));Assert.Equal("invalid_cart",(await Assert.ThrowsAsync<BusinessException>(()=>reader.ReadCheckoutVariantsAsync("fr",[],CancellationToken.None))).Code);Assert.Equal("invalid_cart",(await Assert.ThrowsAsync<BusinessException>(()=>reader.ReadCheckoutVariantsAsync("fa",Enumerable.Range(0,65).Select(i=>"v"+i).ToArray(),CancellationToken.None))).Code);Assert.Equal(System.Data.ConnectionState.Closed,scope.ServiceProvider.GetRequiredService<CatalogDbContext>().Database.GetDbConnection().State);}
    [Fact] public async Task NativePublicFailureIs503NoStoreWithoutSampleCatalogueFallback(){var stub=DispatchProxy.Create<ICatalogService,UnavailableCatalog>();using var host=factory.WithWebHostBuilder(b=>b.ConfigureTestServices(s=>s.AddSingleton(stub)));using var client=host.CreateClient();using var r=await client.GetAsync("/api/storefront/fa?metadataOnly=true");Assert.Equal(HttpStatusCode.ServiceUnavailable,r.StatusCode);Assert.Contains("no-store",r.Headers.CacheControl!.ToString());var body=await r.Content.ReadAsStringAsync();Assert.Contains("catalog_unavailable",body);Assert.DoesNotContain("products",body);}
    public class UnavailableCatalog:DispatchProxy{protected override object? Invoke(MethodInfo? targetMethod,object?[]? args)=>throw new BusinessException("catalog_unavailable","Unstable test-only catalogue.");}
}
